/**
 * Unit tests for AbstractCommandLineRunner#doRun.
 * Since doRun is protected, we use a Testable subclass.
 */
public class AbstractCommandLineRunner_doRun_TriageGen0Test {

    private TestableRunner runner;

    @Mock
    private Compiler<CompilerOptions> mockCompiler;

    @Mock
    private CompilerOptions mockOptions;

    @Mock
    private CommandLineConfig mockConfig;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);

        runner = spy(new TestableRunner());

        // Setup default config behavior
        when(runner.getCommandLineConfig()).thenReturn(mockConfig);
        when(mockConfig.loggingLevel).thenReturn("WARNING");

        // Setup compiler and options injection
        doReturn(mockCompiler).when(runner).createCompiler();
        doReturn(mockOptions).when(runner).createOptions();

        // Mock options default file path to empty to avoid file IO logic unless needed
        mockOptions.jsOutputFile = "";

        // Mock result processing to return 0 (success)
        doReturn(0).when(runner).processResults(any(Result.class), any(), any(CompilerOptions.class));
    }

    /**
     * Test case for the standard compilation path (no modules).
     */
    @Test
    public void testDoRun_StandardCompilation() throws Exception {
        // Arrange
        when(mockConfig.js).thenReturn(Arrays.asList("file1.js", "file2.js"));
        when(mockConfig.module).thenReturn(Collections.emptyList());

        List<JSSourceFile> mockExterns = Collections.emptyList();
        List<JSSourceFile> mockInputs = Collections.singletonList(mock(JSSourceFile.class));
        Result mockResult = mock(Result.class);

        doReturn(mockExterns).when(runner).createExterns();
        doReturn(mockInputs).when(runner).createSourceInputs(mockConfig.js);
        when(mockCompiler.compile(mockExterns, mockInputs, mockOptions)).thenReturn(mockResult);

        // Act
        int result = runner.doRun();

        // Assert
        assertEquals(0, result);
        verify(mockCompiler).compile(mockExterns, mockInputs, mockOptions);
    }

    /**
     * Test case for the module compilation path.
     */
    @Test
    public void testDoRun_ModuleCompilation() throws Exception {
        // Arrange
        when(mockConfig.js).thenReturn(Collections.singletonList("main.js"));
        when(mockConfig.module).thenReturn(Collections.singletonList("module1.js"));

        List<JSSourceFile> mockExterns = Collections.emptyList();
        List<JSModule> mockModules = Collections.singletonList(mock(JSModule.class));
        Result mockResult = mock(Result.class);

        doReturn(mockExterns).when(runner).createExterns();
        doReturn(mockModules).when(runner).createJsModules(mockConfig.module, mockConfig.js);
        when(mockCompiler.compileModules(mockExterns, mockModules, mockOptions)).thenReturn(mockResult);

        // Act
        int result = runner.doRun();

        // Assert
        assertEquals(0, result);
        verify(mockCompiler).compileModules(mockExterns, mockModules, mockOptions);
    }

    /**
     * Test case for when output is written to a file.
     */
    @Test
    public void testDoRun_WriteToFile() throws Exception {
        // Arrange
        mockOptions.jsOutputFile = "output.js";
        when(mockConfig.js).thenReturn(Collections.emptyList());
        when(mockConfig.module).thenReturn(Collections.emptyList());

        // Mock the output writer creation
        PrintWriter mockWriter = mock(PrintWriter.class);
        Closeable mockCloseableWriter = mock(Closeable.class);
        // We use a spy/mock to simulate the writer being a Closeable
        doReturn(mockCloseableWriter).when(runner).fileNameToOutputWriter("output.js");

        doReturn(Collections.emptyList()).when(runner).createExterns();
        doReturn(Collections.emptyList()).when(runner).createSourceInputs(any());
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mock(Result.class));

        // Act
        runner.doRun();

        // Assert
        verify(mockCloseableWriter).close();
    }

    /**
     * Test case for when output is an OutputStream (Stdout/Stderr style).
     */
    @Test
    public void testDoRun_OutputStreamToWriter() throws Exception {
        // Arrange
        when(mockConfig.js).thenReturn(Collections.emptyList());
        when(mockConfig.module).thenReturn(Collections.emptyList());

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // Wrapper to make it look like an OutputStream that the code expects
        doReturn(baos).when(runner).getOutput(); 
        // Note: The logic in doRun checks 'out instanceof OutputStream'
        // In the real class, 'out' is a field. We simulate it via the spy.

        doReturn(mock(PrintWriter.class)).when(runner).streamToOutputWriter(any(OutputStream.class));
        doReturn(Collections.emptyList()).when(runner).createExterns();
        doReturn(Collections.emptyList()).when(runner).createSourceInputs(any());
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mock(Result.class));

        // Act
        runner.doRun();

        // Assert
        // Verify logic flows through the else if branch
    }

    /**
     * Concrete implementation of AbstractCommandLineRunner for testing.
     */
    private static class TestableRunner extends AbstractCommandLineRunner<CompilerOptions> {
        private OutputStream out = new ByteArrayOutputStream();

        @Override
        protected Compiler<CompilerOptions> createCompiler() {
            return null; // Handled by Mockito
        }

        @Override
        protected CompilerOptions createOptions() {
            return null; // Handled by Mockito
        }

        @Override
        protected void setRunOptions(CompilerOptions options) throws FlagUsageException, IOException {}

        @Override
        protected List<JSSourceFile> createSourceInputs(List<String> files) throws FlagUsageException, IOException {
            return Collections.emptyList();
        }

        @Override
        protected List<JSModule> createJsModules(List<String> moduleSpecs, List<String> jsFiles) throws FlagUsageException, IOException {
            return Collections.emptyList();
        }

        @Override
        protected List<JSSourceFile> createExterns() throws FlagUsageException, IOException {
            return Collections.emptyList();
        }

        @Override
        protected PrintWriter fileNameToOutputWriter(String fileName) throws IOException {
            return null; 
        }

        @Override
        protected PrintWriter streamToOutputWriter(OutputStream os) {
            return null;
        }

        // Helper to inject 'out' field behavior for the test
        protected OutputStream getOutput() {
            return out;
        }

        // Since 'out' is a protected field in the base class, 
        // we access it via reflection or by providing a setter in the testable class 
        // if the base class allows. For this test, we assume we can manipulate the protected field.

        @Override
        protected int processResults(Result result, List<JSModule> modules, CompilerOptions options) {
            return 0;
        }

        @Override
        protected void checkModuleName(String name) {}

        @Override
        protected List<JSSourceFile> createInputs(List<String> files, boolean allowStdIn) { return null; }

        @Override
        protected void initOptionsFromFlags(CompilerOptions options) {}

        @Override
        protected DiagnosticGroups getDiagnosticGroups() { return null; }

        @Override
        protected boolean isInTestMode() { return true; }

        // Mocking the output writer logic because the original code uses 'out'
        // In a real scenario, 'out' is a protected field in AbstractCommandLineRunner.
        // We must ensure the test can set it.
        public void setOut(Object o) throws Exception {
            java.lang.reflect.Field field = AbstractCommandLineRunner.class.getDeclaredField("out");
            field.setAccessible(true);
            field.set(this, o);
        }

        // Override to allow the test to bypass the file IO and use the spy-setup
        @Override
        protected PrintWriter fileNameToOutputWriter(String fileName) throws IOException {
            return null; 
        }
    }
}
